class AuthHandler {
  constructor(provider) {
    this.provider = provider;
  }

  parse(raw) {
    return { provider: this.provider, raw };
  }

  static create(provider) {
    return new AuthHandler(provider);
  }
}

const h = AuthHandler.create("lti");
console.log(h.parse("tok")); // { provider: 'lti', raw: 'tok' }
console.log(typeof AuthHandler); // function

class AuthHandler {
  constructor(provider) {
    this.provider = provider;
  }
  parse(raw) {
    return raw;
  }
}

class LtiHandler extends AuthHandler {
  constructor(provider, version) {
    super(provider); // must run before this.version
    this.version = version;
  }
  parse(raw) {
    const base = super.parse(raw);
    return { kind: "lti", v: this.version, raw: base };
  }
}

const h = new LtiHandler("lti", 1);
console.log(h instanceof AuthHandler); // true

