class CacheEntry {
  constructor(key) {
    this.key = key;
    return { hijacked: true }; // replaces instance!
  }
}

const e = new CacheEntry("k1");
console.log(e.key);              // undefined
console.log(e.hijacked);         // true
console.log(e instanceof CacheEntry); // false
